contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, address newOwner) public {
        // No require on c.owner() before the call that establishes it.
        // We can safely call transferOwnership as an arbitrary caller; it may revert.

        address beforeOwner = c.owner();

        bool reverted;
        if (caller == address(this)) {
            // This test contract is the initial owner (it deployed c), so this path can succeed.
            try c.transferOwnership(newOwner) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // Delegate the transferOwnership call?  We cannot change msg.sender of c calls.
            // msg.sender for every call on c is this contract, so the only way to invoke as
            // a non-owner is impossible here; nevertheless the rule must be general.
            try c.transferOwnership(newOwner) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // General rule: msg.sender (this contract) is c's owner at entry because it deployed c.
        // Thus transferOwnership is only callable by the owner; success implies owner == newOwner,
        // and any revert leaves owner unchanged.
        assert(reverted ? c.owner() == beforeOwner : c.owner() == newOwner);
    }

    receive() external payable {}
}

