contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address newOwner) public payable {
        address ownerBefore = c.owner();

        // As msg.sender is this contract and deployed c, ownerBefore should be address(this).
        // Thus ownerCallReverted must be false (successful).
        bool ownerCallReverted;
        try c.owned() {
            ownerCallReverted = false;
        } catch {
            ownerCallReverted = true;
        }

        // Any address, including zero, is allowed by transferOwnership.
        // This call changes owner to newOwner.
        c.transferOwnership(newOwner);

        address ownerAfter = c.owner();

        // Now only newOwner (msg.sender if same) can call owned().
        bool newOwnerCallReverted;
        try c.owned() {
            newOwnerCallReverted = false;
        } catch {
            newOwnerCallReverted = true;
        }

        // General rule:
        // 1. Before transfer, the current owner (this contract) can call owned() without revert.
        // 2. After transferring to newOwner, owned() succeeds iff msg.sender == newOwner.
        //    Since msg.sender here is this contract, if newOwner != address(this), it should revert;
        //    if newOwner == address(this), it should succeed.
        assert(
            !ownerCallReverted &&
            ownerAfter == newOwner &&
            (newOwner == msg.sender ? !newOwnerCallReverted : newOwnerCallReverted)
        );
    }

    receive() external payable {}
}

